package com.bananalab.lite;
import java.util.*;import java.text.*;
/** Extractive retrieval: does not claim that snippets are an original reasoned answer. */
final class ResearchAnswer{
 static Set<String> terms(String input){Set<String> out=new LinkedHashSet<>();for(String s:Knowledge.normalize(input).split("[^a-z0-9]+"))if(s.length()>2&&!s.matches("que|como|por|para|una|uno|los|las|del|con|sobre|son|esta|esto|eso|ese|esa|hay|porque|cual|cuales|puede|puedo|podes|quiero|busca|buscar|internet|explicame|decime|contame|mas|informacion|favor|entre|diferencia|comparar|compara|actualiza|actualizado|tema"))out.add(s);return out;}
 static double score(String q,String text){Set<String> need=terms(q),have=terms(text);double n=0;for(String s:need)if(have.contains(s))n++;return need.isEmpty()?0:n/Math.sqrt(need.size());}
 static String date(long millis){return new SimpleDateFormat("dd/MM/yyyy HH:mm",Locale.ROOT).format(new Date(millis));}
 static String excerpt(String query,String body){return excerpt(query,body,0);}
 static String excerpt(String query,String body,int depth){List<String> sentences=new ArrayList<>();for(String s:body.replaceAll("\\s+"," ").split("(?<=[.!?])\\s+")){if(s.length()<25||s.matches("(?is).*(?:https?://|www\\.|disponible en:|como citar|cómo citar|consultado (?:el|en)|skip to content).*")||sentences.contains(s))continue;sentences.add(s);}Collections.sort(sentences,(a,b)->Double.compare(score(query,b)-b.length()*.00005,score(query,a)-a.length()*.00005));if(depth>=sentences.size())return depth==0?"No encontré un fragmento legible suficiente.":"No hay otro fragmento legible en esta copia; pedí actualizar o una pregunta más concreta.";String[] words=sentences.get(depth).trim().split("\\s+");return JavaCompat.join(" ",Arrays.copyOf(words,Math.min(25,words.length)))+(words.length>25?"…":"");}
 static String render(String query,List<ResearchWeb.Doc> docs,boolean cached,String warning){return render(query,docs,cached,warning,0);}
 static String render(String query,List<ResearchWeb.Doc> docs,boolean cached,String warning,int depth){StringBuilder b=new StringBuilder(cached?"Fuentes guardadas (sin consulta nueva) sobre ":"Consulté fuentes para: ");b.append(query).append("\n");if(!warning.isEmpty())b.append("\n").append(warning).append("\n");int i=0;Set<String> seen=new HashSet<>();for(ResearchWeb.Doc d:docs){if(i==3)break;if(!seen.add(d.url)||score(query,d.title+" "+d.text)<=0)continue;i++;b.append("\n[").append(i).append("] ").append(d.title).append("\nFragmento: “").append(excerpt(query,d.text,depth)).append("”\n").append(d.url).append("\nConsultada: ").append(date(d.saved));if(System.currentTimeMillis()-d.saved>7*ResearchStore.DAY)b.append(" · guardada hace más de una semana");b.append("\n");}if(i==0)b.append("\nNo encontré evidencia pertinente suficiente. Probá con una pregunta más concreta.");else b.append("\nEstos son fragmentos recuperados, no una respuesta verificada. La fecha es de consulta, no de publicación. Podés pedir ‘amplia eso’, ‘actualiza eso’ o ‘compara … con …’.");return b.toString();}
}
